"Form 1, your declaration that you are fit to drive": "ಫಾರ್ಮ್ 1, ವಾಹನ ಚಲಾಯಿಸಲು ಸಮರ್ಥರೆಂಬ ನಿಮ್ಮ ಘೋಷಣೆ",
