"Go": "ಹೋಗಿ",
"Go to an Aadhaar Seva Kendra with your Aadhaar card and the new phone. Walk in or book a slot online.": "ನಿಮ್ಮ ಆಧಾರ್ ಕಾರ್ಡ್ ಮತ್ತು ಹೊಸ ಫೋನ್‌ನೊಂದಿಗೆ ಆಧಾರ್ ಸೇವಾ ಕೇಂದ್ರಕ್ಕೆ ಹೋಗಿ. ನೇರವಾಗಿ ಹೋಗಿ ಅಥವಾ ಆನ್‌ಲೈನ್ ಸ್ಲಾಟ್ ಬುಕ್ ಮಾಡಿ.",
"Go to an Aadhaar Seva Kendra with your Aadhaar card. Walk in or book a slot online.": "ನಿಮ್ಮ ಆಧಾರ್ ಕಾರ್ಡ್‌ನೊಂದಿಗೆ ಆಧಾರ್ ಸೇವಾ ಕೇಂದ್ರಕ್ಕೆ ಹೋಗಿ. ನೇರವಾಗಿ ಹೋಗಿ ಅಥವಾ ಆನ್‌ಲೈನ್ ಸ್ಲಾಟ್ ಬುಕ್ ಮಾಡಿ.",
"Go with your old passport and the self-attested copies.": "ನಿಮ್ಮ ಹಳೆಯ ಪಾಸ್‌ಪೋರ್ಟ್ ಮತ್ತು ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿಗಳೊಂದಿಗೆ ಹೋಗಿ.",
"Go with your originals and one set of self-attested copies.": "ನಿಮ್ಮ ಮೂಲ ದಾಖಲೆಗಳು ಮತ್ತು ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿಗಳ ಒಂದು ಸೆಟ್‌ನೊಂದಿಗೆ ಹೋಗಿ.",
"Holding two PANs can bring a ₹10,000 penalty. If you already have one, apply for a correction instead.": "ಎರಡು ಪ್ಯಾನ್ ಇದ್ದರೆ ₹10,000 ದಂಡ ಬೀಳಬಹುದು. ಈಗಾಗಲೇ ಒಂದಿದ್ದರೆ, ಬದಲಿಗೆ ತಿದ್ದುಪಡಿಗೆ ಅರ್ಜಿ ಹಾಕಿ.",
