"Interest rate": "ಬಡ್ಡಿ ದರ",
"Interest rates and processing fees differ by bank, so there is no single fair price to check against. Compare offers before you choose.": "ಬಡ್ಡಿ ದರ ಮತ್ತು ಸಂಸ್ಕರಣಾ ಶುಲ್ಕ ಬ್ಯಾಂಕ್‌ನಿಂದ ಬ್ಯಾಂಕ್‌ಗೆ ಬೇರೆ, ಹಾಗಾಗಿ ಹೋಲಿಸಲು ಒಂದೇ ನ್ಯಾಯ ಬೆಲೆ ಇಲ್ಲ. ಆರಿಸುವ ಮೊದಲು ಆಫರ್‌ಗಳನ್ನು ಹೋಲಿಸಿ.",
"Interest subsidy": "ಬಡ್ಡಿ ಸಹಾಯಧನ",
"Interest you repay can be deducted from taxable income under section 80E, for up to 8 years, under the old tax regime.": "ನೀವು ಮರುಪಾವತಿಸುವ ಬಡ್ಡಿಯನ್ನು ಹಳೆಯ ತೆರಿಗೆ ಪದ್ಧತಿಯಲ್ಲಿ ಸೆಕ್ಷನ್ 80E ಅಡಿ 8 ವರ್ಷಗಳವರೆಗೆ ತೆರಿಗೆಗೊಳಪಡುವ ಆದಾಯದಿಂದ ಕಳೆಯಬಹುದು.",
"KYC for you and your co-applicant": "ನಿಮ್ಮ ಮತ್ತು ಸಹ-ಅರ್ಜಿದಾರರ KYC",
"Karnataka uses e-stamp paper only.": "ಕರ್ನಾಟಕದಲ್ಲಿ ಇ-ಸ್ಟ್ಯಾಂಪ್ ಕಾಗದ ಮಾತ್ರ ಬಳಕೆಯಲ್ಲಿದೆ.",
"Keep a signed copy each.": "ಎರಡೂ ಕಡೆ ಸಹಿ ಮಾಡಿದ ಒಂದೊಂದು ಪ್ರತಿ ಇಟ್ಟುಕೊಳ್ಳಿ.",
"Keep the acknowledgement number to track your application.": "ಅರ್ಜಿಯ ಸ್ಥಿತಿ ತಿಳಿಯಲು ಸ್ವೀಕೃತಿ ಸಂಖ್ಯೆ ಇಟ್ಟುಕೊಳ್ಳಿ.",
"Keep the acknowledgement slip and track the update with it.": "ಸ್ವೀಕೃತಿ ಚೀಟಿ ಇಟ್ಟುಕೊಳ್ಳಿ, ಅದರ ಮೂಲಕ ನವೀಕರಣದ ಸ್ಥಿತಿ ನೋಡಿ.",
"Keep the reference number to track the request.": "ಮನವಿಯ ಸ್ಥಿತಿ ತಿಳಿಯಲು ಉಲ್ಲೇಖ ಸಂಖ್ಯೆ ಇಟ್ಟುಕೊಳ್ಳಿ.",
