"Know when the moratorium ends: the course period plus one year under PM-Vidyalaxmi. Repayments start after it.": "ಮೊರಟೋರಿಯಂ ಯಾವಾಗ ಮುಗಿಯುತ್ತದೆ ಎಂದು ತಿಳಿಯಿರಿ: PM-ವಿದ್ಯಾಲಕ್ಷ್ಮಿಯಲ್ಲಿ ಕೋರ್ಸ್ ಅವಧಿ ಜೊತೆಗೆ ಒಂದು ವರ್ಷ. ನಂತರ ಮರುಪಾವತಿ ಶುರುವಾಗುತ್ತದೆ.",
