", usually quiet.": ", ಸಾಮಾನ್ಯವಾಗಿ ಶಾಂತ.",
"A PAN, a tax return and a loan open the door to bank accounts, formal jobs and credit. The guides walk through each one.": "ಪ್ಯಾನ್, ತೆರಿಗೆ ರಿಟರ್ನ್ ಮತ್ತು ಸಾಲ ಬ್ಯಾಂಕ್ ಖಾತೆ, ಔಪಚಾರಿಕ ಉದ್ಯೋಗ ಮತ್ತು ಸಾಲಕ್ಕೆ ಬಾಗಿಲು ತೆರೆಯುತ್ತವೆ. ಮಾರ್ಗದರ್ಶಿಗಳು ಪ್ರತಿಯೊಂದನ್ನೂ ಹಂತ ಹಂತವಾಗಿ ವಿವರಿಸುತ್ತವೆ.",
"Aadhaar address": "ಆಧಾರ್ ವಿಳಾಸ",
"Aadhaar fees, documents and centres:": "ಆಧಾರ್ ಶುಲ್ಕ, ದಾಖಲೆಗಳು ಮತ್ತು ಕೇಂದ್ರಗಳು:",
"About": "ನಮ್ಮ ಬಗ್ಗೆ",
"About Bring Go Pay": "Bring Go Pay ಬಗ್ಗೆ",
"Add a document": "ದಾಖಲೆ ಸೇರಿಸಿ",
"Add a number, a photo or a PDF to any document below.": "ಕೆಳಗಿನ ಯಾವುದೇ ದಾಖಲೆಗೆ ಸಂಖ್ಯೆ, ಫೋಟೋ ಅಥವಾ PDF ಸೇರಿಸಿ.",
"Add a photo or PDF": "ಫೋಟೋ ಅಥವಾ PDF ಸೇರಿಸಿ",
"Add a reminder": "ಜ್ಞಾಪನೆ ಸೇರಿಸಿ",
"Add another document": "ಇನ್ನೊಂದು ದಾಖಲೆ ಸೇರಿಸಿ",
"Add number or copy": "ಸಂಖ್ಯೆ ಅಥವಾ ಪ್ರತಿ ಸೇರಿಸಿ",
"Add to calendar": "ಕ್ಯಾಲೆಂಡರ್‌ಗೆ ಸೇರಿಸಿ",
"Address and hours": "ವಿಳಾಸ ಮತ್ತು ಸಮಯ",
"Address, name, birth date or mobile update": "ವಿಳಾಸ, ಹೆಸರು, ಜನ್ಮ ದಿನಾಂಕ ಅಥವಾ ಮೊಬೈಲ್ ನವೀಕರಣ",
"Agents outside offices quote any price. Without the official fee you can't tell a fair service charge from a markup. Each guide shows the official fee and checks a quote against it.": "ಕಚೇರಿಗಳ ಹೊರಗೆ ಏಜೆಂಟರು ಮನಬಂದ ಬೆಲೆ ಹೇಳುತ್ತಾರೆ. ಅಧಿಕೃತ ಶುಲ್ಕ ತಿಳಿಯದೆ ನ್ಯಾಯವಾದ ಸೇವಾ ಶುಲ್ಕ ಮತ್ತು ಹೆಚ್ಚುವರಿ ಬೆಲೆಯ ವ್ಯತ್ಯಾಸ ಗೊತ್ತಾಗದು. ಪ್ರತಿ ಮಾರ್ಗದರ್ಶಿ ಅಧಿಕೃತ ಶುಲ್ಕ ತೋರಿಸಿ, ಹೇಳಿದ ಬೆಲೆಯನ್ನು ಅದರೊಂದಿಗೆ ಹೋಲಿಸುತ್ತದೆ.",
"All": "ಎಲ್ಲಾ",
"All data cleared": "ಎಲ್ಲಾ ದತ್ತಾಂಶ ಅಳಿಸಲಾಗಿದೆ",
"All packed": "ಎಲ್ಲಾ ಸಿದ್ಧ",
"Amount quoted": "ಹೇಳಿದ ಬೆಲೆ",
"Amount you were quoted": "ನಿಮಗೆ ಹೇಳಿದ ಬೆಲೆ",
"An estimate on the amount alone. Interest during the course and the moratorium is extra unless a subsidy covers it. Your sanction letter has the exact figures.": "ಮೊತ್ತದ ಮೇಲಿನ ಅಂದಾಜು ಮಾತ್ರ. ಸಹಾಯಧನ ಭರಿಸದಿದ್ದರೆ ಕೋರ್ಸ್ ಮತ್ತು ಮೊರಟೋರಿಯಂ ಅವಧಿಯ ಬಡ್ಡಿ ಹೆಚ್ಚುವರಿ. ನಿಖರ ಅಂಕಿಗಳು ನಿಮ್ಮ ಮಂಜೂರಾತಿ ಪತ್ರದಲ್ಲಿರುತ್ತವೆ.",
"An independent civic-tech pilot, not a government website.": "ಸ್ವತಂತ್ರ ನಾಗರಿಕ-ತಂತ್ರಜ್ಞಾನ ಪೈಲಟ್, ಸರ್ಕಾರಿ ಜಾಲತಾಣವಲ್ಲ.",
"Any one": "ಯಾವುದಾದರೂ ಒಂದು",
"Anyone who uses this browser can open this page. Add a passcode and everything here is encrypted, so it opens only with the passcode.": "ಈ ಬ್ರೌಸರ್ ಬಳಸುವ ಯಾರಾದರೂ ಈ ಪುಟ ತೆರೆಯಬಹುದು. ಪಾಸ್‌ಕೋಡ್ ಸೇರಿಸಿದರೆ ಇಲ್ಲಿನ ಎಲ್ಲವೂ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗುತ್ತದೆ, ಪಾಸ್‌ಕೋಡ್‌ನಿಂದ ಮಾತ್ರ ತೆರೆಯುತ್ತದೆ.",
"Appearance": "ಗೋಚರತೆ",
"Applicant": "ಅರ್ಜಿದಾರ",
"Apply for a correction on Protean or UTIITSL. You get the corrected card by post.": "Protean ಅಥವಾ UTIITSLನಲ್ಲಿ ತಿದ್ದುಪಡಿಗೆ ಅರ್ಜಿ ಹಾಕಿ. ತಿದ್ದಿದ ಕಾರ್ಡ್ ಅಂಚೆಯಲ್ಲಿ ಬರುತ್ತದೆ.",
"Apply for the driving licence on sarathi.parivahan.gov.in under Karnataka, pay the fee and book a driving test slot at the RTO for your address. On the day, go with your vehicle and documents.": "sarathi.parivahan.gov.in ನಲ್ಲಿ ಕರ್ನಾಟಕ ಆರಿಸಿ ಚಾಲನಾ ಪರವಾನಗಿಗೆ ಅರ್ಜಿ ಹಾಕಿ, ಶುಲ್ಕ ಪಾವತಿಸಿ, ನಿಮ್ಮ ವಿಳಾಸದ RTOದಲ್ಲಿ ಪರೀಕ್ಷಾ ಸ್ಲಾಟ್ ಬುಕ್ ಮಾಡಿ. ಆ ದಿನ ನಿಮ್ಮ ವಾಹನ ಮತ್ತು ದಾಖಲೆಗಳೊಂದಿಗೆ ಹೋಗಿ.",
"Apply in advance from": "ಮುಂಚಿತ ಅರ್ಜಿ ದಿನಾಂಕ",
"Apply on Protean or UTIITSL. The card comes to you by post, and you get an e-PAN too.": "Protean ಅಥವಾ UTIITSLನಲ್ಲಿ ಅರ್ಜಿ ಹಾಕಿ. ಕಾರ್ಡ್ ಅಂಚೆಯಲ್ಲಿ ಬರುತ್ತದೆ, ಇ-ಪ್ಯಾನ್ ಕೂಡ ಸಿಗುತ್ತದೆ.",
"Apply on sarathi.parivahan.gov.in and choose Karnataka. Upload your documents, pay the fee and book your learner's licence test.": "sarathi.parivahan.gov.in ನಲ್ಲಿ ಅರ್ಜಿ ಹಾಕಿ ಕರ್ನಾಟಕ ಆರಿಸಿ. ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, ಶುಲ್ಕ ಪಾವತಿಸಿ, ಕಲಿಕಾ ಪರವಾನಗಿ ಪರೀಕ್ಷೆ ಬುಕ್ ಮಾಡಿ.",
