"Earliest test": "ಮೊದಲ ಪರೀಕ್ಷಾ ದಿನಾಂಕ",
"Education loan:": "ಶಿಕ್ಷಣ ಸಾಲ:",
"Eight guides for Bengaluru paperwork. Pick one to see what to bring, when to go and what to pay.": "ಬೆಂಗಳೂರಿನ ದಾಖಲೆ ಕೆಲಸಗಳಿಗೆ ಎಂಟು ಮಾರ್ಗದರ್ಶಿಗಳು. ಒಂದನ್ನು ಆರಿಸಿ, ಏನು ತರಬೇಕು, ಯಾವಾಗ ಹೋಗಬೇಕು, ಎಷ್ಟು ಪಾವತಿಸಬೇಕು ನೋಡಿ.",
"Eight guides for Bengaluru. Each one answers all three questions.": "ಬೆಂಗಳೂರಿಗೆ ಎಂಟು ಮಾರ್ಗದರ್ಶಿಗಳು. ಪ್ರತಿಯೊಂದೂ ಮೂರೂ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಿಸುತ್ತದೆ.",
"Enter the amount, the rate and the years to see an estimate.": "ಅಂದಾಜು ನೋಡಲು ಮೊತ್ತ, ದರ ಮತ್ತು ವರ್ಷಗಳನ್ನು ನಮೂದಿಸಿ.",
"Enter the date your learner's licence was issued. It is not saved.": "ಕಲಿಕಾ ಪರವಾನಗಿ ನೀಡಿದ ದಿನಾಂಕ ನಮೂದಿಸಿ. ಇದು ಉಳಿಯುವುದಿಲ್ಲ.",
"Enter your date of birth. It is not saved.": "ನಿಮ್ಮ ಜನ್ಮ ದಿನಾಂಕ ನಮೂದಿಸಿ. ಇದು ಉಳಿಯುವುದಿಲ್ಲ.",
"Enter your passcode to open them.": "ಇವುಗಳನ್ನು ತೆರೆಯಲು ಪಾಸ್‌ಕೋಡ್ ನಮೂದಿಸಿ.",
"Estimate, not live data. Times are in Bengaluru.": "ಅಂದಾಜು, ನೇರ ದತ್ತಾಂಶ ಅಲ್ಲ. ಸಮಯ ಬೆಂಗಳೂರಿನದು.",
"Every government errand raises three questions: what to bring, when to go, and what to pay. Bring Go Pay answers all three in one guide per task, so the first trip is the only trip.": "ಪ್ರತಿ ಸರ್ಕಾರಿ ಕೆಲಸದಲ್ಲಿ ಮೂರು ಪ್ರಶ್ನೆಗಳು: ಏನು ತರಬೇಕು, ಯಾವಾಗ ಹೋಗಬೇಕು, ಎಷ್ಟು ಪಾವತಿಸಬೇಕು. Bring Go Pay ಪ್ರತಿ ಕೆಲಸಕ್ಕೆ ಒಂದು ಮಾರ್ಗದರ್ಶಿಯಲ್ಲಿ ಮೂರಕ್ಕೂ ಉತ್ತರಿಸುತ್ತದೆ, ಹೀಗಾಗಿ ಮೊದಲ ಭೇಟಿಯೇ ಕೊನೆಯದು.",
"Every official fee": "ಎಲ್ಲಾ ಅಧಿಕೃತ ಶುಲ್ಕಗಳು",
"Everything here is saved in this browser's own storage. Nothing is uploaded, and nobody else can see it from their device. Clearing your browser data, or Clear all data in Settings, deletes it.": "ಇಲ್ಲಿನ ಎಲ್ಲವೂ ಈ ಬ್ರೌಸರ್‌ನ ಸ್ವಂತ ಸಂಗ್ರಹದಲ್ಲಿ ಉಳಿಯುತ್ತದೆ. ಏನನ್ನೂ ಅಪ್‌ಲೋಡ್ ಮಾಡಲಾಗುವುದಿಲ್ಲ, ಬೇರೆ ಯಾರೂ ತಮ್ಮ ಸಾಧನದಿಂದ ನೋಡಲಾಗದು. ಬ್ರೌಸರ್ ದತ್ತಾಂಶ ಅಳಿಸಿದರೆ ಅಥವಾ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ 'ಎಲ್ಲಾ ದತ್ತಾಂಶ ಅಳಿಸಿ' ಒತ್ತಿದರೆ ಇದು ಅಳಿಯುತ್ತದೆ.",
"Everything is saved on this device only. No sign-up, and nothing is uploaded.": "ಎಲ್ಲವೂ ಈ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತದೆ. ಸೈನ್-ಅಪ್ ಇಲ್ಲ, ಏನನ್ನೂ ಅಪ್‌ಲೋಡ್ ಮಾಡಲಾಗುವುದಿಲ್ಲ.",
"Exact fee": "ನಿಖರ ಶುಲ್ಕ",
"Exactly right": "ಸರಿಯಾಗಿಯೇ ಇದೆ",
"Exactly what to carry, as a checklist you tick while you pack. It can fill itself from the documents you already have.": "ಏನು ಒಯ್ಯಬೇಕು ಎಂಬುದನ್ನು ಪ್ಯಾಕ್ ಮಾಡುವಾಗ ಗುರುತಿಸುವ ಪರಿಶೀಲನಾಪಟ್ಟಿಯಾಗಿ. ನಿಮ್ಮಲ್ಲಿರುವ ದಾಖಲೆಗಳಿಂದ ಇದು ತಾನಾಗಿಯೇ ತುಂಬಿಕೊಳ್ಳಬಹುದು.",
