"Fair-price bands: pilot estimates by the project team, not official figures.": "ನ್ಯಾಯ ಬೆಲೆ ಮಿತಿಗಳು: ಯೋಜನಾ ತಂಡದ ಪೈಲಟ್ ಅಂದಾಜು, ಅಧಿಕೃತ ಅಂಕಿಗಳಲ್ಲ.",
