"GO": "ಹೋಗಿ",
"Get your e-PAN on incometax.gov.in with an OTP sent to the phone linked to your Aadhaar. There is no office visit.": "ಆಧಾರ್‌ಗೆ ಲಿಂಕ್ ಆದ ಫೋನ್‌ಗೆ ಬರುವ OTP ಮೂಲಕ incometax.gov.in ನಲ್ಲಿ ನಿಮ್ಮ ಇ-ಪ್ಯಾನ್ ಪಡೆಯಿರಿ. ಕಚೇರಿಗೆ ಹೋಗಬೇಕಿಲ್ಲ.",
