"Its number, notes and copies are removed from this device. This cannot be undone.": "ಇದರ ಸಂಖ್ಯೆ, ಟಿಪ್ಪಣಿ ಮತ್ತು ಪ್ರತಿಗಳು ಈ ಸಾಧನದಿಂದ ಅಳಿಯುತ್ತವೆ. ಇದನ್ನು ಹಿಂಪಡೆಯಲಾಗದು.",
"Jump to a guide": "ಮಾರ್ಗದರ್ಶಿಗೆ ಹೋಗಿ",
"Karnataka uses e-stamp paper only. Buy it on SHCIL online or at an authorised centre, then sign the agreement at home with two witnesses.": "ಕರ್ನಾಟಕದಲ್ಲಿ ಇ-ಸ್ಟ್ಯಾಂಪ್ ಕಾಗದ ಮಾತ್ರ. SHCIL ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಅಥವಾ ಅಧಿಕೃತ ಕೇಂದ್ರದಲ್ಲಿ ಖರೀದಿಸಿ, ನಂತರ ಮನೆಯಲ್ಲೇ ಇಬ್ಬರು ಸಾಕ್ಷಿಗಳೊಂದಿಗೆ ಒಪ್ಪಂದಕ್ಕೆ ಸಹಿ ಮಾಡಿ.",
"Keep your Aadhaar, PAN and other numbers and copies on this device, ready for any form.": "ನಿಮ್ಮ ಆಧಾರ್, ಪ್ಯಾನ್ ಮತ್ತು ಇತರ ಸಂಖ್ಯೆಗಳು ಹಾಗೂ ಪ್ರತಿಗಳನ್ನು ಈ ಸಾಧನದಲ್ಲೇ ಇಡಿ, ಯಾವುದೇ ಫಾರ್ಮ್‌ಗೆ ಸಿದ್ಧ.",
"Keep your document numbers and copies in one place, ready for the next form that asks for them.": "ನಿಮ್ಮ ದಾಖಲೆ ಸಂಖ್ಯೆಗಳು ಮತ್ತು ಪ್ರತಿಗಳನ್ನು ಒಂದೇ ಕಡೆ ಇಡಿ, ಮುಂದಿನ ಫಾರ್ಮ್‌ಗೆ ಸಿದ್ಧ.",
