"Three answers.": "ಮೂರು ಉತ್ತರಗಳು.",
"One-tap “How long did you wait?” reports replace the estimates. Guides in Kannada and Hindi.": "ಒಂದೇ ಟ್ಯಾಪ್‌ನ “ಎಷ್ಟು ಹೊತ್ತು ಕಾದಿರಿ?” ವರದಿಗಳು ಅಂದಾಜುಗಳ ಬದಲಾಗುತ್ತವೆ. ಕನ್ನಡ ಮತ್ತು ಹಿಂದಿಯಲ್ಲಿ ಮಾರ್ಗದರ್ಶಿಗಳು.",
