"Pages": "ಪುಟಗಳು",
"Paid document pre-checks, for people who want their papers looked over before they go.": "ಹೋಗುವ ಮೊದಲು ತಮ್ಮ ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿಕೊಳ್ಳಲು ಬಯಸುವವರಿಗೆ ಶುಲ್ಕಸಹಿತ ಮುಂಗಡ ಪರಿಶೀಲನೆ.",
