"Passport Seva Kendras work by appointment. Book the calmest slot you can get on passportindia.gov.in or the mPassport Seva app.": "ಪಾಸ್‌ಪೋರ್ಟ್ ಸೇವಾ ಕೇಂದ್ರಗಳು ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ಮೂಲಕ ಕೆಲಸ ಮಾಡುತ್ತವೆ. passportindia.gov.in ಅಥವಾ mPassport Seva ಆ್ಯಪ್‌ನಲ್ಲಿ ಸಿಗುವ ಅತಿ ಶಾಂತ ಸ್ಲಾಟ್ ಬುಕ್ ಮಾಡಿ.",
"Passport Seva helpline:": "ಪಾಸ್‌ಪೋರ್ಟ್ ಸೇವಾ ಸಹಾಯವಾಣಿ:",
