"Pay.": "ಪಾವತಿಸಿ.",
"People find out a document is missing at the counter, after queuing, and have to come back. Each guide lists what to carry, and you tick things off as you pack.": "ಸರತಿಯಲ್ಲಿ ನಿಂತ ನಂತರ ಕೌಂಟರ್‌ನಲ್ಲಿ ದಾಖಲೆ ಮರೆತಿರುವುದು ಗೊತ್ತಾಗಿ ಮತ್ತೆ ಬರಬೇಕಾಗುತ್ತದೆ. ಪ್ರತಿ ಮಾರ್ಗದರ್ಶಿ ಏನು ಒಯ್ಯಬೇಕು ಎಂದು ಪಟ್ಟಿ ಮಾಡುತ್ತದೆ, ನೀವು ಪ್ಯಾಕ್ ಮಾಡುತ್ತಾ ಗುರುತಿಸುತ್ತೀರಿ.",
