"Pick a guide": "ಮಾರ್ಗದರ್ಶಿ ಆರಿಸಿ",
"Pick your task and we’ll tell you exactly what to bring, when to go and what to pay.": "ನಿಮ್ಮ ಕೆಲಸ ಆರಿಸಿ, ಏನು ತರಬೇಕು, ಯಾವಾಗ ಹೋಗಬೇಕು, ಎಷ್ಟು ಪಾವತಿಸಬೇಕು ಎಂದು ನಾವು ಹೇಳುತ್ತೇವೆ.",
"Pilot estimate.": "ಪೈಲಟ್ ಅಂದಾಜು.",
"Plain guides for Bengaluru paperwork, so your first trip is the only one.": "ಬೆಂಗಳೂರಿನ ದಾಖಲೆ ಕೆಲಸಗಳಿಗೆ ಸರಳ ಮಾರ್ಗದರ್ಶಿಗಳು, ಹೀಗಾಗಿ ನಿಮ್ಮ ಮೊದಲ ಭೇಟಿಯೇ ಕೊನೆಯದು.",
