"That's less than the official fee. Ask what's included and keep the receipt.": "ಇದು ಅಧಿಕೃತ ಶುಲ್ಕಕ್ಕಿಂತ ಕಡಿಮೆ. ಏನೆಲ್ಲ ಸೇರಿದೆ ಎಂದು ಕೇಳಿ, ರಸೀದಿ ಇಟ್ಟುಕೊಳ್ಳಿ.",
