"The Education loan guide explains PM-Vidyalaxmi, interest subsidies and the moratorium, so cost is less of a barrier to college.": "ಶಿಕ್ಷಣ ಸಾಲ ಮಾರ್ಗದರ್ಶಿ PM-ವಿದ್ಯಾಲಕ್ಷ್ಮಿ, ಬಡ್ಡಿ ಸಹಾಯಧನ ಮತ್ತು ಮೊರಟೋರಿಯಂ ವಿವರಿಸುತ್ತದೆ, ಹೀಗಾಗಿ ಕಾಲೇಜಿಗೆ ವೆಚ್ಚ ಕಡಿಮೆ ಅಡ್ಡಿಯಾಗುತ್ತದೆ.",
"The calmest time on the day you pick, with directions and a calendar reminder. Or skip the trip when it can be done online.": "ನೀವು ಆರಿಸಿದ ದಿನದ ಅತಿ ಶಾಂತ ಸಮಯ, ದಾರಿ ಮತ್ತು ಕ್ಯಾಲೆಂಡರ್ ಜ್ಞಾಪನೆಯೊಂದಿಗೆ. ಅಥವಾ ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಆಗುವುದಾದರೆ ಭೇಟಿಯನ್ನೇ ತಪ್ಪಿಸಿ.",
"The calmest time to visit each office, from a model of how they usually fill up.": "ಪ್ರತಿ ಕಚೇರಿಗೆ ಭೇಟಿ ನೀಡಲು ಅತಿ ಶಾಂತ ಸಮಯ, ಅಲ್ಲಿ ಸಾಮಾನ್ಯವಾಗಿ ಜನ ಹೇಗೆ ಸೇರುತ್ತಾರೆ ಎಂಬ ಮಾದರಿಯಿಂದ.",
"The goals we work towards": "ನಾವು ಕೆಲಸ ಮಾಡುವ ಗುರಿಗಳು",
"The late-filing deadline has passed. Check incometax.gov.in for your options.": "ತಡವಾಗಿ ಸಲ್ಲಿಸುವ ಗಡುವು ಮುಗಿದಿದೆ. ನಿಮ್ಮ ಆಯ್ಕೆಗಳಿಗಾಗಿ incometax.gov.in ನೋಡಿ.",
"The official fee, and an instant check of any agent’s quote, so you can tell a fair service charge from a markup.": "ಅಧಿಕೃತ ಶುಲ್ಕ, ಮತ್ತು ಯಾವುದೇ ಏಜೆಂಟರು ಹೇಳಿದ ಬೆಲೆಯ ತಕ್ಷಣದ ಪರಿಶೀಲನೆ, ಹೀಗಾಗಿ ನ್ಯಾಯ ಸೇವಾ ಶುಲ್ಕ ಮತ್ತು ಹೆಚ್ಚುವರಿ ಬೆಲೆಯ ವ್ಯತ್ಯಾಸ ತಿಳಿಯುತ್ತದೆ.",
