"Tick what you have at home. Guides then show “You have it” and can tick those for you. This list keeps only which documents you have; numbers and copies live in your vault.": "ಮನೆಯಲ್ಲಿರುವುದನ್ನು ಗುರುತಿಸಿ. ನಂತರ ಮಾರ್ಗದರ್ಶಿಗಳು “ನಿಮ್ಮಲ್ಲಿದೆ” ಎಂದು ತೋರಿಸಿ ಅವನ್ನು ನಿಮಗಾಗಿ ಗುರುತಿಸಬಹುದು. ಇಲ್ಲಿ ದಾಖಲೆಗಳ ಹೆಸರು ಮಾತ್ರ ಉಳಿಯುತ್ತದೆ; ಸಂಖ್ಯೆ ಮತ್ತು ಪ್ರತಿಗಳು ನನ್ನ ದಾಖಲೆಗಳ ವಾಲ್ಟ್‌ನಲ್ಲಿರುತ್ತವೆ.",
"Tick what you have in My documents first.": "ಮೊದಲು ನನ್ನ ದಾಖಲೆಗಳಲ್ಲಿ ನಿಮ್ಮಲ್ಲಿರುವುದನ್ನು ಗುರುತಿಸಿ.",
