"Planned measures for the pilot. There are no results yet.": "ಪೈಲಟ್‌ಗಾಗಿ ಯೋಜಿಸಿದ ಅಳತೆಗಳು. ಇನ್ನೂ ಯಾವುದೇ ಫಲಿತಾಂಶಗಳಿಲ್ಲ.",
"We mainly tackle Goal 16 by making government paperwork transparent and fair. We support Goals 10, 1 and 9 by giving everyone equal access, saving money for people on low incomes, and using technology to do it.": "ಸರ್ಕಾರಿ ದಾಖಲೆ ಕೆಲಸವನ್ನು ಪಾರದರ್ಶಕ ಮತ್ತು ನ್ಯಾಯಯುತವಾಗಿಸುವ ಮೂಲಕ ನಾವು ಮುಖ್ಯವಾಗಿ ಗುರಿ 16ರತ್ತ ಕೆಲಸ ಮಾಡುತ್ತೇವೆ. ಎಲ್ಲರಿಗೂ ಸಮಾನ ಪ್ರವೇಶ ನೀಡಿ, ಕಡಿಮೆ ಆದಾಯದವರ ಹಣ ಉಳಿಸಿ ಮತ್ತು ಅದಕ್ಕಾಗಿ ತಂತ್ರಜ್ಞಾನ ಬಳಸಿ ನಾವು ಗುರಿ 10, 1 ಮತ್ತು 9ಕ್ಕೆ ಬೆಂಬಲ ನೀಡುತ್ತೇವೆ.",
"Bring Go Pay, in one line": "ಒಂದೇ ಸಾಲಿನಲ್ಲಿ Bring Go Pay",
"Loading the guides…": "ಮಾರ್ಗದರ್ಶಿಗಳು ಲೋಡ್ ಆಗುತ್ತಿವೆ…",
"Not connected to the database yet": "ಇನ್ನೂ ಡೇಟಾಬೇಸ್‌ಗೆ ಸಂಪರ್ಕಗೊಂಡಿಲ್ಲ",
"This copy of the site has no Supabase address or key. Set SUPABASE_URL and SUPABASE_PUBLISHABLE_KEY, then build it again.": "ಸೈಟ್‌ನ ಈ ಪ್ರತಿಯಲ್ಲಿ Supabase ವಿಳಾಸ ಅಥವಾ ಕೀ ಇಲ್ಲ. SUPABASE_URL ಮತ್ತು SUPABASE_PUBLISHABLE_KEY ಹೊಂದಿಸಿ, ನಂತರ ಮತ್ತೆ ನಿರ್ಮಿಸಿ.",
"Couldn’t load the guides": "ಮಾರ್ಗದರ್ಶಿಗಳನ್ನು ಲೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ",
"Check your internet connection and try again.": "ನಿಮ್ಮ ಇಂಟರ್ನೆಟ್ ಸಂಪರ್ಕ ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
